1	package com.maritime.platform.common.core.security;
2	
3	import javax.crypto.Cipher;
4	import javax.crypto.SecretKey;
5	import javax.crypto.spec.GCMParameterSpec;
6	import javax.crypto.spec.SecretKeySpec;
7	import java.nio.ByteBuffer;
8	import java.nio.charset.StandardCharsets;
9	import java.security.MessageDigest;
10	import java.security.SecureRandom;
11	import java.util.Base64;
12	
13	/**
14	 * AES-256-GCM encryption for JWT tokens.
15	 *
16	 * <p>Wraps a signed JWT string into an opaque encrypted blob
17	 * so the client cannot read the claims. The gateway decrypts
18	 * before JWT signature verification.
19	 *
20	 * <p>Format: Base64(IV[12] + ciphertext + tag[16])
21	 *
22	 * <p>Derives the AES key from the JWT shared secret via
23	 * SHA-256, so no additional key management is needed.
24	 */
25	public final class JwtEncryptor {
26	
27	    private static final String AES_GCM = "AES/GCM/NoPadding";
28	    private static final int IV_LENGTH = 12;
29	    private static final int TAG_LENGTH_BITS = 128;
30	    private static final SecureRandom RANDOM = new SecureRandom();
31	
32	    private final SecretKey aesKey;
33	
34	    /**
35	     * @param jwtSecret the same shared secret used for JWT signing.
36	     *                  SHA-256 derived to produce a 256-bit AES key.
37	     */
38	    public JwtEncryptor(String jwtSecret) {
39	        this.aesKey = deriveKey(jwtSecret);
40	    }
41	
42	    /**
43	     * Encrypt a signed JWT string into an opaque Base64 blob.
44	     */
45	    public String encrypt(String jwt) {
46	        try {
47	            byte[] plaintext = jwt.getBytes(StandardCharsets.UTF_8);
48	            byte[] iv = new byte[IV_LENGTH];
49	            RANDOM.nextBytes(iv);
50	
51	            Cipher cipher = Cipher.getInstance(AES_GCM);
52	            cipher.init(Cipher.ENCRYPT_MODE, aesKey,
53	                    new GCMParameterSpec(TAG_LENGTH_BITS, iv));
54	            byte[] ciphertext = cipher.doFinal(plaintext);
55	
56	            // IV + ciphertext (includes GCM tag)
57	            ByteBuffer buffer = ByteBuffer.allocate(
58	                    IV_LENGTH + ciphertext.length);
59	            buffer.put(iv);
60	            buffer.put(ciphertext);
61	
62	            return Base64.getUrlEncoder().withoutPadding()
63	                    .encodeToString(buffer.array());
64	        } catch (Exception e) {
65	            throw new IllegalStateException(
66	                    "JWT encryption failed", e);
67	        }
68	    }
69	
70	    /**
71	     * Decrypt an opaque Base64 blob back to the signed JWT string.
72	     *
73	     * @return the original JWT string, or null if decryption fails
74	     */
75	    public String decrypt(String encryptedToken) {
76	        try {
77	            byte[] decoded = Base64.getUrlDecoder()
78	                    .decode(encryptedToken);
79	            if (decoded.length < IV_LENGTH + 1) {
80	                return null;
81	            }
82	
83	            ByteBuffer buffer = ByteBuffer.wrap(decoded);
84	            byte[] iv = new byte[IV_LENGTH];
85	            buffer.get(iv);
86	            byte[] ciphertext = new byte[buffer.remaining()];
87	            buffer.get(ciphertext);
88	
89	            Cipher cipher = Cipher.getInstance(AES_GCM);
90	            cipher.init(Cipher.DECRYPT_MODE, aesKey,
91	                    new GCMParameterSpec(TAG_LENGTH_BITS, iv));
92	            byte[] plaintext = cipher.doFinal(ciphertext);
93	
94	            return new String(plaintext, StandardCharsets.UTF_8);
95	        } catch (Exception e) {
96	            return null;
97	        }
98	    }
99	
100	    private static SecretKey deriveKey(String secret) {
101	        try {
102	            MessageDigest sha256 = MessageDigest.getInstance("SHA-256");
103	            byte[] keyBytes = sha256.digest(
104	                    secret.getBytes(StandardCharsets.UTF_8));
105	            return new SecretKeySpec(keyBytes, "AES");
106	        } catch (Exception e) {
107	            throw new IllegalStateException(
108	                    "AES key derivation failed", e);
109	        }
110	    }
111	}
