1	package com.maritime.platform.common.core.security;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.util.HexFormat;
6	
7	/**
8	 * Client fingerprint computation for token binding.
9	 *
10	 * <p>Generates a SHA-256 hash of (clientIP + User-Agent) to bind
11	 * JWT tokens to a specific client environment. Gateway verifies
12	 * the fingerprint on every request — a stolen token used from a
13	 * different IP or browser will be rejected.
14	 *
15	 * <p>The hash is truncated to 16 hex chars (64 bits) to keep
16	 * the JWT compact while providing sufficient collision resistance
17	 * for session-scoped binding.
18	 */
19	public final class ClientFingerprint {
20	
21	    private static final int FINGERPRINT_LENGTH = 16;
22	
23	    private ClientFingerprint() {
24	    }
25	
26	    /**
27	     * Compute fingerprint from client IP and User-Agent.
28	     *
29	     * @param clientIp  client IP address (may be null)
30	     * @param userAgent User-Agent header (may be null)
31	     * @return 16-char hex fingerprint
32	     */
33	    public static String compute(String clientIp, String userAgent) {
34	        String raw = normalize(clientIp) + "|" + normalize(userAgent);
35	        try {
36	            MessageDigest md = MessageDigest.getInstance("SHA-256");
37	            byte[] hash = md.digest(
38	                    raw.getBytes(StandardCharsets.UTF_8));
39	            return HexFormat.of().formatHex(hash)
40	                    .substring(0, FINGERPRINT_LENGTH);
41	        } catch (Exception e) {
42	            throw new IllegalStateException(
43	                    "SHA-256 not available", e);
44	        }
45	    }
46	
47	    private static String normalize(String value) {
48	        return value == null ? "" : value.trim();
49	    }
50	}
