1	package com.maritime.platform.common.security.jwt;
2	
3	import com.maritime.platform.common.core.exception.BusinessException;
4	import com.maritime.platform.common.core.result.ResultCode;
5	import com.maritime.platform.common.security.context.SecurityUser;
6	import io.jsonwebtoken.Claims;
7	import io.jsonwebtoken.ExpiredJwtException;
8	import io.jsonwebtoken.Jwts;
9	import io.jsonwebtoken.security.Keys;
10	import jakarta.annotation.PostConstruct;
11	import org.springframework.stereotype.Component;
12	
13	import javax.crypto.SecretKey;
14	import java.nio.charset.StandardCharsets;
15	import java.util.Date;
16	
17	/**
18	 * Creates and validates JWT tokens using JJWT (HS256).
19	 */
20	@Component
21	public class JwtTokenProvider {
22	
23	    private final JwtProperties properties;
24	    private SecretKey signingKey;
25	
26	    public JwtTokenProvider(JwtProperties properties) {
27	        this.properties = properties;
28	    }
29	
30	    @PostConstruct
31	    public void init() {
32	        byte[] keyBytes = properties.getSecret().getBytes(StandardCharsets.UTF_8);
33	        this.signingKey = Keys.hmacShaKeyFor(keyBytes);
34	    }
35	
36	    /**
37	     * Creates an access token carrying the full user context.
38	     */
39	    public String createAccessToken(SecurityUser user) {
40	        Date now = new Date();
41	        long expirationMs = properties.getAccessTokenExpirationMinutes() * 60 * 1000;
42	        Date expiration = new Date(now.getTime() + expirationMs);
43	
44	        return Jwts.builder()
45	                .subject(user.userId())
46	                .claim("userId", user.userId())
47	                .claim("userName", user.userName())
48	                .claim("activeOrgCode", user.activeOrgCode())
49	                .claim("systemScope", user.systemScope())
50	                .claim("sessionId", user.sessionId())
51	                .issuer(properties.getIssuer())
52	                .issuedAt(now)
53	                .expiration(expiration)
54	                .signWith(signingKey)
55	                .compact();
56	    }
57	
58	    /**
59	     * Creates a refresh token with only the session identifier.
60	     */
61	    public String createRefreshToken(String sessionId) {
62	        Date now = new Date();
63	        long expirationMs = properties.getRefreshTokenExpirationHours() * 60 * 60 * 1000;
64	        Date expiration = new Date(now.getTime() + expirationMs);
65	
66	        return Jwts.builder()
67	                .claim("sessionId", sessionId)
68	                .issuer(properties.getIssuer())
69	                .issuedAt(now)
70	                .expiration(expiration)
71	                .signWith(signingKey)
72	                .compact();
73	    }
74	
75	    /**
76	     * Parses and validates a JWT token, returning its claims.
77	     *
78	     * @throws BusinessException with {@code AUTH_TOKEN_EXPIRED} or {@code AUTH_TOKEN_INVALID}
79	     */
80	    public Claims parseToken(String token) {
81	        try {
82	            return Jwts.parser()
83	                    .verifyWith(signingKey)
84	                    .build()
85	                    .parseSignedClaims(token)
86	                    .getPayload();
87	        } catch (ExpiredJwtException e) {
88	            throw new BusinessException(ResultCode.AUTH_TOKEN_EXPIRED, e);
89	        } catch (Exception e) {
90	            throw new BusinessException(ResultCode.AUTH_TOKEN_INVALID, e);
91	        }
92	    }
93	}
