9	import org.springframework.boot.context.properties.EnableConfigurationProperties;
10	import org.springframework.context.annotation.Bean;
11	
12	/**
13	 * Auto-configuration for IAM security components.
14	 *
15	 * <p>Registers beans conditionally — does NOT use @ComponentScan
16	 * to avoid clashing with business systems that have their own
17	 * security aspects (e.g., todo-center's RequirePermissionAspect).
18	 */
19	@AutoConfiguration
20	@EnableConfigurationProperties(JwtProperties.class)
21	public class SecurityAutoConfiguration {
22	
23	    @Bean
24	    @ConditionalOnBean(PermissionChecker.class)
25	    @ConditionalOnMissingBean(name = "requirePermissionAspect")
26	    RequirePermissionAspect iamRequirePermissionAspect(
27	            PermissionChecker permissionChecker) {
28	        return new RequirePermissionAspect(permissionChecker);
29	    }
30	}
