16	import org.springframework.lang.NonNull;
17	import org.springframework.stereotype.Component;
18	import org.springframework.web.filter.OncePerRequestFilter;
19	
20	/**
21	 * Extracts gateway-injected user headers and populates
22	 * {@link SecurityContextHolder} for downstream services.
23	 *
24	 * <p>Gateway's JwtAuthGlobalFilter injects these headers after
25	 * JWT verification:
26	 * <ul>
27	 *   <li>{@code X-User-Id}</li>
28	 *   <li>{@code X-User-Name} (URL-encoded)</li>
29	 *   <li>{@code X-Active-Org-Code}</li>
30	 *   <li>{@code X-Session-Id}</li>
31	 *   <li>{@code X-System-Scope} (comma-separated)</li>
32	 * </ul>
33	 *
34	 * <p>Runs before business interceptors (order = Ordered.HIGHEST_PRECEDENCE + 5).
35	 */
36	@Component
37	@Order(Ordered.HIGHEST_PRECEDENCE + 5)
38	public class GatewayUserContextFilter extends OncePerRequestFilter {
39	
40	    private static final String HEADER_USER_ID = "X-User-Id";
41	    private static final String HEADER_USER_NAME = "X-User-Name";
42	    private static final String HEADER_ACTIVE_ORG_CODE =
43	            "X-Active-Org-Code";
44	    private static final String HEADER_SESSION_ID = "X-Session-Id";
45	    private static final String HEADER_SYSTEM_SCOPE =
46	            "X-System-Scope";
47	
48	    @Override
49	    protected void doFilterInternal(
50	            @NonNull HttpServletRequest request,
51	            @NonNull HttpServletResponse response,
52	            @NonNull FilterChain filterChain)
53	            throws ServletException, IOException {
54	        String userId = request.getHeader(HEADER_USER_ID);
55	        if (userId != null && !userId.isBlank()) {
56	            String userName = urlDecode(
57	                    request.getHeader(HEADER_USER_NAME));
58	            String activeOrgCode =
59	                    request.getHeader(HEADER_ACTIVE_ORG_CODE);
60	            String sessionId =
61	                    request.getHeader(HEADER_SESSION_ID);
62	            List<String> systemScope = parseScope(
63	                    request.getHeader(HEADER_SYSTEM_SCOPE));
64	
65	            SecurityContextHolder.set(new SecurityUser(
66	                    userId, userName, activeOrgCode,
67	                    systemScope, sessionId));
68	        }
69	        try {
70	            filterChain.doFilter(request, response);
71	        } finally {
72	            SecurityContextHolder.clear();
73	        }
74	    }
75	
76	    private static String urlDecode(String value) {
77	        if (value == null || value.isBlank()) {
78	            return value;
79	        }
80	        return URLDecoder.decode(value, StandardCharsets.UTF_8);
81	    }
82	
83	    private static List<String> parseScope(String scopeHeader) {
84	        if (scopeHeader == null || scopeHeader.isBlank()) {
85	            return List.of();
86	        }
87	        return Arrays.asList(scopeHeader.split(","));
88	    }
89	}
