8	import io.swagger.v3.oas.models.security.SecurityScheme;
9	import org.springframework.boot.autoconfigure.AutoConfiguration;
10	import org.springframework.boot.autoconfigure.condition.ConditionalOnClass;
11	import org.springframework.boot.autoconfigure.condition.ConditionalOnMissingBean;
12	import org.springframework.boot.context.properties.EnableConfigurationProperties;
13	import org.springframework.context.annotation.Bean;
14	
15	@AutoConfiguration
16	@ConditionalOnClass(OpenAPI.class)
17	@EnableConfigurationProperties(OpenApiProperties.class)
18	public class PlatformOpenApiAutoConfiguration {
19	
20	    public static final String BEARER_AUTH_SCHEME = "bearerAuth";
21	
22	    @Bean
23	    @ConditionalOnMissingBean
24	    public OpenAPI platformOpenApi(OpenApiProperties props) {
25	        OpenAPI api = new OpenAPI()
26	                .info(new Info()
27	                        .title(props.getTitle())
28	                        .description(props.getDescription())
29	                        .version(props.getVersion())
30	                        .contact(new Contact().name(props.getContactName())));
31	
32	        if (props.isEnableBearerAuth()) {
33	            Components components = api.getComponents() == null
34	                    ? new Components() : api.getComponents();
35	            components.addSecuritySchemes(BEARER_AUTH_SCHEME,
36	                    new SecurityScheme()
37	                            .type(SecurityScheme.Type.HTTP)
38	                            .scheme("bearer")
39	                            .bearerFormat("JWT")
40	                            .description("JWT Bearer token issued by iam-auth-service"));
41	            api.components(components);
42	            api.addSecurityItem(new SecurityRequirement().addList(BEARER_AUTH_SCHEME));
43	        }
44	
45	        return api;
46	    }
47	}
