package com.maritime.platform.gateway.security.jwt;

import com.maritime.platform.gateway.security.GatewayPrincipal;
import com.maritime.platform.gateway.security.GatewaySecurityProperties;
import io.jsonwebtoken.Claims;
import org.springframework.util.CollectionUtils;

import java.util.Collections;
import java.util.List;

public class DefaultJwtClaimsMapper implements JwtClaimsMapper {

    private final GatewaySecurityProperties.Claims claimsConfig;

    public DefaultJwtClaimsMapper(GatewaySecurityProperties.Claims claimsConfig) {
        this.claimsConfig = claimsConfig;
    }

    @Override
    public GatewayPrincipal.User map(Claims claims) {
        String userId = claims.get(claimsConfig.getUserId(), String.class);
        String sessionId = claims.get(claimsConfig.getSessionId(), String.class);
        String userName = claims.get(claimsConfig.getUserName(), String.class);
        String activeOrgCode = claims.get(claimsConfig.getActiveOrgCode(), String.class);
        String activeOrgName = claims.get(claimsConfig.getActiveOrgName(), String.class);
        String userSource = claims.get(claimsConfig.getUserSource(), String.class);
        String tenantId = claims.get(claimsConfig.getTenantId(), String.class);

        List<String> systemScope = resolveSystemScope(claims);

        return new GatewayPrincipal.User(
                userId, userName, sessionId,
                activeOrgCode, activeOrgName,
                systemScope, userSource, tenantId
        );
    }

    private List<String> resolveSystemScope(Claims claims) {
        Object value = claims.get(claimsConfig.getSystemScope());
        if (value instanceof List<?> list) {
            return list.stream()
                    .filter(String.class::isInstance)
                    .map(String.class::cast)
                    .toList();
        }
        if (value instanceof String str && !str.isBlank()) {
            return List.of(str);
        }
        return List.of();
    }
}
